package store

import (
	"database/sql"
	"errors"

	"github.com/reliant-labs/forge/pkg/svcerr"
)

// missing is what a hand-written read returns for a row that is not there:
// svcerr.NotFound(entity), the shape every generated by-key getter gives a
// miss, carrying sql.ErrNoRows as its cause.
//
// Both halves matter. The kind is what a handler's svcerr.Wrap reads, so a
// miss reaches the client as NotFound "<entity> not found" — never as the
// Internal an unclassified sql.ErrNoRows becomes, and never with driver text.
// The cause keeps errors.Is(err, sql.ErrNoRows) true for the callers that
// branch on absence deliberately (a project with no config record, a setting
// that falls back to its default).
//
// svcerr itself must not learn sql.ErrNoRows: a raw ErrNoRows that reaches a
// handler can be a row our own code requires, which is a server fault. Only
// the read that ran the query knows the miss is the caller's, so it is
// classified here.
func missing(entity string) error {
	return svcerr.WithCause(svcerr.NotFound(entity), sql.ErrNoRows)
}

// classifyMissing turns a raw sql.ErrNoRows from a hand-written query (a bun
// Scan, a RETURNING that matched nothing) into missing(entity). Any other
// error, an already-classified miss included, is returned unchanged.
func classifyMissing(err error, entity string) error {
	if errors.Is(err, sql.ErrNoRows) && !svcerr.IsNotFound(err) {
		return missing(entity)
	}
	return err
}
